<script setup lang="ts">
import { ref, watch, computed } from 'vue';
import { state, report, loadReport, today, message } from '../store.ts';
import { exportCSVs, download } from '../export.ts';
import { cashFlows, reportFor, type Bill } from '../domain.ts';
import Money from './Money.vue';
import Icon from './Icon.vue';
import DonutChart from './DonutChart.vue';
import { allocationBreakdown } from '../../../../supabase/functions/_shared/planning.ts';
import { localDay } from '../domain.ts';
const emit = defineEmits<{ bill: [bill: Bill]; budget: [] }>();
const period = ref('month'), month = ref(today().slice(0,7)), loading = ref(false), error = ref('');
const range = computed(() => { const [year, selectedMonth] = month.value.split('-').map(Number); return period.value === 'year' ? { from: `${year}-01-01`, to: `${year}-12-31` } : { from: `${month.value}-01`, to: `${month.value}-${new Date(Date.UTC(year, selectedMonth, 0)).getUTCDate()}` }; });
const difference = computed(() => BigInt(report.value.personalIncome) - BigInt(report.value.personalExpense));
const cash = computed(() => cashFlows(state.data, range.value.from, range.value.to, state.timezone));
const trends = computed(() => Array.from({ length: 3 }, (_, index) => {
  const [year, selectedMonth] = month.value.split('-').map(Number);
  const date = new Date(Date.UTC(year, selectedMonth - 3 + index, 1));
  const key = date.toISOString().slice(0,7), end = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate();
  return { month: key, ...reportFor(state.data, `${key}-01`, `${key}-${end}`, state.timezone) };
}));
const allocations = computed(() => report.value.allocations ?? allocationBreakdown(report.value.categories, state.data.transactions.filter(row => !row.deleted && row.kind === 'expense' && row.goalID && localDay(row.occurredAt, state.timezone) >= range.value.from && localDay(row.occurredAt, state.timezone) <= range.value.to).map(row => ({ categoryID: row.categoryID, goalID: row.goalID!, amount: row.amount })), state.data.goals ?? [], state.data.categories, new Set(state.data.budgets.filter(row => row.month.slice(0,7) >= range.value.from.slice(0,7) && row.month.slice(0,7) <= range.value.to.slice(0,7)).map(row => row.categoryID))));
const flows = computed(() => [{ id: 'income', name: 'Pemasukan', amount: report.value.personalIncome }, { id: 'expense', name: 'Pengeluaran', amount: report.value.personalExpense }]);
const maximumTrend = computed(() => trends.value.reduce((largest, row) => { const amount = BigInt(row.personalIncome) > BigInt(row.personalExpense) ? BigInt(row.personalIncome) : BigInt(row.personalExpense); return amount > largest ? amount : largest; }, 1n));
const trendHeight = (amount: string) => Number(BigInt(amount) * 10000n / maximumTrend.value) / 100;
let revision = 0;
async function refresh() { const current = ++revision; loading.value = true; error.value = ''; try { await loadReport(range.value.from, range.value.to); } catch (cause) { if (current === revision) error.value = message(cause); } finally { if (current === revision) loading.value = false; } }
watch([range, () => state.data, () => state.timezone], refresh, { immediate: true });
function exportCSV(name: string) { const all = exportCSVs(state.data, range.value.from, range.value.to, state.timezone); download(name, all[name as keyof typeof all]); state.notice = `CSV periode ${range.value.from} sampai ${range.value.to} diunduh.`; }
</script>
<template><div class="report-toolbar"><label>Periode<input v-model="month" type="month" required></label><div class="segmented compact"><button :class="{ active: period === 'month' }" @click="period = 'month'">Bulanan</button><button :class="{ active: period === 'year' }" @click="period = 'year'">Tahunan</button></div><details class="export-menu"><summary class="secondary"><Icon name="download" /> Ekspor CSV</summary><button v-for="name in Object.keys(exportCSVs(state.data))" :key="name" class="text-button" @click="exportCSV(name)">{{ name }}</button></details></div><p v-if="loading" role="status" class="callout sky">Memuat laporan…</p><div v-else-if="error" role="alert" class="callout"><p>{{ error }}</p><button class="secondary" @click="refresh">Coba lagi</button></div><template v-else><div class="stats-grid"><article class="card mint"><span>Pemasukan pribadi</span><h2><Money :amount="report.personalIncome" prefix="+" /></h2></article><article class="card peach"><span>Pengeluaran pribadi</span><h2><Money :amount="report.personalExpense" prefix="−" /></h2></article><article class="card"><span>Selisih periode</span><h2><Money :amount="difference" /></h2></article></div><div class="report-charts"><DonutChart title="Alokasi pengeluaran" :rows="allocations" /><DonutChart title="Pemasukan & pengeluaran" :rows="flows" /></div><section class="card report-breakdown"><div class="section-heading"><div><h2>Pengeluaran per kategori</h2></div><span class="icon-tile lavender"><Icon name="reports" /></span></div><div v-if="!report.categories.length" class="empty"><h3>Belum ada pengeluaran</h3><p>Catatan periode ini akan muncul di sini.</p></div><div v-for="(row,index) in report.categories" :key="row.categoryID" class="category-bar"><div class="section-heading"><span class="category-name"><span class="legend-dot" :class="['mint','sky','peach','sun','lavender'][index % 5]"></span>{{ state.data.categories.find(category => category.id === row.categoryID)?.name ?? 'Kategori' }}</span><Money :amount="row.amount" /></div><progress :value="Number(row.amount)" :max="Number(report.personalExpense) || 1" :aria-label="`Pengeluaran kategori ${state.data.categories.find(category => category.id === row.categoryID)?.name}`"></progress></div></section><div class="two-column"><section class="card"><h2>Posisi hari ini</h2><div class="list-row"><span>Piutang · belum diterima</span><Money :amount="state.data.overview.receivables" /></div><div class="list-row"><span>Utang · belum dibayar</span><Money :amount="state.data.overview.payables" /></div><div class="list-row"><strong>Posisi bersih</strong><Money :amount="state.data.overview.netPosition" /></div></section><section class="card"><div class="section-heading"><h2>Anggaran</h2><Icon name="budget" /></div><button class="text-button" @click="emit('budget')">Kelola anggaran <Icon name="next" /></button><details class="help-disclosure"><summary>Tentang laporan</summary><p>Laporan menghitung porsi Anda, termasuk biaya nonkas. Arus kas mencatat seluruh uang masuk dan keluar akun. Transfer serta pelunasan tidak dihitung dua kali.</p><p>Posisi hari ini menggunakan saldo terkini, bukan saldo penutupan periode.</p></details></section></div><section class="card cash-report"><h2>Arus kas per akun</h2><div v-for="row in cash" :key="row.accountID" class="cash-account"><h3>{{ state.data.accounts.find(account => account.id === row.accountID)?.name }}</h3><div class="form-grid"><span>Masuk <Money :amount="row.incoming" prefix="+" /></span><span>Keluar <Money :amount="row.outgoing" prefix="−" /></span><strong>Arus bersih <Money :amount="row.net" /></strong></div></div></section><section class="card"><h2>Perbandingan tiga bulan</h2><div class="chart-key"><span><span class="chart-dot" style="background:var(--income)"></span>Pemasukan</span><span><span class="chart-dot" style="background:var(--expense)"></span>Pengeluaran</span></div><div class="comparison-chart" role="img" aria-label="Grafik perbandingan pemasukan dan pengeluaran tiga bulan"><div v-for="row in trends" :key="row.month" class="comparison-group"><div class="comparison-bars"><div class="comparison-bar" :style="{ height: `${trendHeight(row.personalIncome)}%` }"></div><div class="comparison-bar expense" :style="{ height: `${trendHeight(row.personalExpense)}%` }"></div></div><span>{{ row.month }}</span></div></div><div v-for="row in trends" :key="row.month" class="trend-row"><strong>{{ row.month }}</strong><span>Pemasukan <Money :amount="row.personalIncome" prefix="+" /></span><span>Pengeluaran <Money :amount="row.personalExpense" prefix="−" /></span></div></section></template></template>
